const payload = $('Execute Workflow Trigger').item.json || {};
const args = payload.payload?.args || payload.args || {};
const msg = payload.message || payload.body?.message || payload || {};

const chatId = String(payload.chatId || msg.chat?.id || '').trim();
const rawText = String(msg.text || payload.text || payload.query || '').trim();

let query = String(args.query || '').trim();
if (!query) {
  query = rawText
    .replace(/^(tim|tìm|tim kiem|tìm kiếm|timkiem|search|tra cuu|tra cứu|google|duckduckgo)\s*/i, '')
    .replace(/^(ve|về|thong tin ve|thông tin về|cho toi biet ve|cho tôi biết về|noi ve|nói về)\s*/i, '')
    .trim();
}

if (!query) query = 'n8n automation';

return [{ json: { chatId, query, rawText } }];

const source = $('Chuẩn Bị Query').item.json || {};
const html = String($json.data || '');

const decodeHtml = (value = '') => String(value)
  .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
  .replace(/&#(\d+);/g, (_, num) => String.fromCodePoint(parseInt(num, 10)))
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>');

const cleanText = (value = '') => decodeHtml(String(value).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());

const extractUrl = (href = '') => {
  const normalized = decodeHtml(href);
  const match = normalized.match(/[?&]uddg=([^&]+)/);
  if (match) {
    try {
      return decodeURIComponent(match[1]);
    } catch (error) {}
  }
  if (normalized.startsWith('//')) return `https:${normalized}`;
  return normalized;
};

const results = [];
const resultRegex = /<a[^>]*class="result__a"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
let match;
while ((match = resultRegex.exec(html)) !== null && results.length < 3) {
  const url = extractUrl(match[1]);
  const title = cleanText(match[2]);
  if (!url || !title) continue;
  if (results.some((item) => item.url === url)) continue;
  results.push({ url, title });
}

let text = `Mia thấy vài kết quả khá khớp với "${source.query}".`;
if (results.length > 0) {
  for (let i = 0; i < results.length; i += 1) {
    const item = results[i];
    text += `\n- ${item.title}`;
  }
  text += '\n\nLink tham khảo:';
  for (let i = 0; i < results.length; i += 1) {
    const item = results[i];
    text += `\n${i + 1}. ${item.url}`;
  }
} else {
  text += '\nMia chưa thấy kết quả nào đủ rõ. Anh Minh thử đổi từ khóa cụ thể hơn nhé.';
}

return [{ json: { chatId: source.chatId || '', text: text.trim() } }];

const source = $input.item.json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2 ($1)')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const rawText = String(
  source.text ||
  source.responseText ||
  source.output ||
  source.response ||
  ''
).trim();

const plainText = String(source.plainText || htmlToPlainText(rawText)).trim();

return [{
  json: {
    ...source,
    text: plainText || rawText
  }
}];
